import { Column, Entity, PrimaryGeneratedColumn } from 'typeorm';

@Entity()
export class Uso {
  @PrimaryGeneratedColumn()
  id!: number;

  @Column()
  nombre!: string;
}

import { Module } from '@nestjs/common';
import { TypeOrmModule } from '@nestjs/typeorm';
import { UsosService } from './usos.service';
import { UsosController } from './usos.controller';
import { Uso } from './entities/uso.entity';

@Module({
  imports: [TypeOrmModule.forFeature([Uso])],
  controllers: [UsosController],
  providers: [UsosService],
})
export class UsosModule {}

import { Injectable, NotFoundException, OnModuleInit } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { CreateUsoDto } from './dto/create-uso.dto';
import { UpdateUsoDto } from './dto/update-uso.dto';
import { Uso } from './entities/uso.entity';

@Injectable()
export class UsosService implements OnModuleInit {
  constructor(
    @InjectRepository(Uso)
    private readonly usosRepository: Repository<Uso>,
  ) {}

  async onModuleInit() {
    const count = await this.usosRepository.count();
    if (count === 0) {
      await this.usosRepository.save([
        { nombre: 'Gaming' },
        { nombre: 'Oficina' },
        { nombre: 'Doméstico' },
        { nombre: 'Estudio' },
      ]);
    }
  }

  create(createUsoDto: CreateUsoDto) {
    return this.usosRepository.save(createUsoDto);
  }

  findAll() {
    return this.usosRepository.find();
  }

  async findOne(id: number) {
    const uso = await this.usosRepository.findOneBy({ id });
    if (!uso) {
      throw new NotFoundException(`El uso con ID ${id} no existe.`);
    }
    return uso;
  }

  async update(id: number, updateUsoDto: UpdateUsoDto) {
    const uso = await this.findOne(id);
    Object.assign(uso, updateUsoDto);
    return this.usosRepository.save(uso);
  }

  async remove(id: number) {
    const result = await this.usosRepository.delete(id);
    if (result.affected === 0) {
      throw new NotFoundException(`El uso con ID ${id} no existe.`);
    }
    return { message: `El uso con ID ${id} ha sido eliminado.`, status: 'success' };
  }
}

import {
  Controller,
  Get,
  Post,
  Body,
  Patch,
  Param,
  Delete,
  ConflictException,
} from '@nestjs/common';
import { UsosService } from './usos.service';
import { CreateUsoDto } from './dto/create-uso.dto';
import { UpdateUsoDto } from './dto/update-uso.dto';

@Controller('usos')
export class UsosController {
  constructor(private readonly usosService: UsosService) {}

  @Post()
  async create(@Body() createUsoDto: CreateUsoDto) {
    const usos = await this.usosService.findAll();
    const existingUso = usos.find((uso) => uso.nombre === createUsoDto.nombre);
    if (existingUso) {
      throw new ConflictException(
        `El uso con nombre "${createUsoDto.nombre}" ya existe.`,
      );
    }
    return this.usosService.create(createUsoDto);
  }

  @Get()
  findAll() {
    return this.usosService.findAll();
  }

  @Get(':id')
  findOne(@Param('id') id: string) {
    return this.usosService.findOne(+id);
  }

  @Patch(':id')
  async update(@Param('id') id: string, @Body() updateUsoDto: UpdateUsoDto) {
    const nombre = updateUsoDto.nombre;
    if (nombre !== undefined) {
      if (nombre.trim() === '') {
        throw new ConflictException('El nombre no puede estar vacío.');
      }
      const usos = await this.usosService.findAll();
      const existingUso = usos.find(
        (uso) => uso.nombre === nombre && uso.id !== +id,
      );
      if (existingUso) {
        throw new ConflictException(
          `El uso con nombre "${nombre}" ya existe.`,
        );
      }
    }
    return this.usosService.update(+id, updateUsoDto);
  }

  @Delete(':id')
  remove(@Param('id') id: string) {
    return this.usosService.remove(+id);
  }
}

