$out = Join-Path $env:TEMP "pc-api2.out.log"; $err = Join-Path $env:TEMP "pc-api2.err.log"
Remove-Item $out,$err -ErrorAction SilentlyContinue
$p = Start-Process node -ArgumentList "dist/main" -RedirectStandardOutput $out -RedirectStandardError $err -PassThru
try {
  $up=$false
  for ($i=0;$i -lt 30;$i++){ if ($p.HasExited){break}; try { Invoke-RestMethod -Uri "http://localhost:3000/usos" -TimeoutSec 2 | Out-Null; $up=$true; break } catch { Start-Sleep -Seconds 1 } }
  if (-not $up){ echo "APP NO RESPONDIO"; Get-Content $out; Get-Content $err; exit 1 }
  echo "=== GET /pc-prearmadas/1 -> precio debe ser numero ==="; $r = Invoke-RestMethod "http://localhost:3000/pc-prearmadas/1"; echo ("precio={0} tipo={1}" -f $r.precio, $r.precio.GetType().Name)
  echo "=== DELETE /usos/1 (tiene PC asociada -> 409) ==="
  try { Invoke-RestMethod "http://localhost:3000/usos/1" -Method Delete | Out-Null } catch { echo "STATUS: $($_.Exception.Response.StatusCode.value__) - $($_.ErrorDetails.Message)" }
  echo "=== DELETE /usos/3 (sin PCs -> ok) ==="; ConvertTo-Json -InputObject (Invoke-RestMethod "http://localhost:3000/usos/3" -Method Delete) -Depth 5
  echo "=== GET /usos ==="; ConvertTo-Json -InputObject (Invoke-RestMethod "http://localhost:3000/usos") -Depth 4
} finally {
  if (-not $p.HasExited){ Stop-Process -Id $p.Id -Force }
}

