  if (-not $up){ echo "APP NO RESPONDIO"; Get-Content $out; Get-Content $err; exit 1 }
  function PostC($b){ Invoke-RestMethod "http://localhost:3001/componentes" -Method Post -ContentType "application/json" -Body $b }
