  PostC '{"nombre":"Ryzen 5 5600","tipo":"Procesador","marca":"AMD","precio":220.50,"usoId":1}' | Out-Null
  PostC '{"nombre":"Intel Core i3 12100","tipo":"Procesador","marca":"Intel","precio":120,"usoId":2}' | Out-Null
  PostC '{"nombre":"Pentium 3","tipo":"Procesador","marca":"Intel","precio":5,"usoId":2}' | Out-Null
  echo "=== GET /componentes (todas, con uso) ==="; ConvertTo-Json -InputObject (Invoke-RestMethod "http://localhost:3001/componentes") -Depth 6
