$out = Join-Path $env:TEMP "pc-api6.out.log"; $err = Join-Path $env:TEMP "pc-api6.err.log"
Remove-Item $out,$err -ErrorAction SilentlyContinue
$env:PORT='3001'; Remove-Item Env:DB_PORT,Env:DB_NAME -ErrorAction SilentlyContinue
$p = Start-Process node -ArgumentList "dist/main" -RedirectStandardOutput $out -RedirectStandardError $err -PassThru
try {
  $base="http://localhost:3001"; $up=$false
  for ($i=0;$i -lt 30;$i++){ if ($p.HasExited){break}; try { Invoke-RestMethod -Uri "$base/usos" -TimeoutSec 2 | Out-Null; $up=$true; break } catch { Start-Sleep -Seconds 1 } }
  if (-not $up){ echo "APP NO RESPONDIO"; Get-Content $err -Tail 10; exit 1 }
  function J($o){ ConvertTo-Json -InputObject $o -Depth 6 }
  echo "=== 1) Buscar categoria: GET /usos?nombre=gam ==="; J (Invoke-RestMethod "$base/usos?nombre=gam")
