  echo "=== 3) Crear componente con ese usoId ==="; $c = Invoke-RestMethod "$base/componentes" -Method Post -ContentType "application/json" -Body ("{`"nombre`":`"CPU Test`",`"tipo`":`"Procesador`",`"marca`":`"AMD`",`"precio`":100,`"usoId`":$($u.id)}"); J $c
  echo "=== 4) Consultar componente (uso LINKADO) ==="; J (Invoke-RestMethod "$base/componentes/$($c.id)")
  echo "=== 5) Editar componente ==="; J (Invoke-RestMethod "$base/componentes/$($c.id)" -Method Patch -ContentType "application/json" -Body '{"precio":150.75}')
  echo "=== 6) Borrar componente ==="; J (Invoke-RestMethod "$base/componentes/$($c.id)" -Method Delete)
  echo "=== 7) Borrar uso ==="; J (Invoke-RestMethod "$base/usos/$($u.id)" -Method Delete)
} finally {
  if (-not $p.HasExited){ Stop-Process -Id $p.Id -Force }
}

